style.css:
/* Roblox Profile Custom Background */
@-moz-document domain("roblox.com") {
body {
        background-image: url("https://i.pinimg.com/originals/39/39/a8/3939a8485b1817679fc4ea7a429b288c.jpg");
        background-size: cover;
        background-attachment: fixed;
        background-repeat: no-repeat;
        background-position: center;
    }

    /* Ajuste a opacidade do conteúdo */
    .container-main, .profile-header, .container-footer {
        background-color: rgba(0, 0, 0, 0.6); /* Fundo semitransparente */
        color: #fff; /* Texto branco para contraste */
    }

    /* Estiliza links e botões */
    a, .btn-primary {
        color: #FFD700; /* Dourado */
    }
}
